#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

struct PluginTable
{
    std::uint32_t size;
    std::uint16_t versionMajor, versionMinor;
    const char* name;
    int (*init)(const void* host);
    void (*update)(double dt);
    void (*shutdown)();
};

constexpr std::uint32_t kMinimumSize{ static_cast<std::uint32_t>(offsetof(PluginTable, update)) };   // 1.0 had no update

std::vector<std::string> validatePlugin(const PluginTable& t, std::uint16_t hostMajor, std::uint16_t hostMinor)
{
    if (t.size < kMinimumSize) return { "table too small" };
    if (t.versionMajor != hostMajor) return { "wrong major version" };
    std::vector<std::string> problems;
    if (t.versionMinor > hostMinor) problems.push_back("needs a newer game");
    if (t.name == nullptr || t.name[0] == '\0') problems.push_back("no name");
    if (t.init == nullptr) problems.push_back("missing init");
    // shutdown sits after update in the struct: a 1.0-sized table cannot have it.
    const bool hasShutdownField{ t.size >= offsetof(PluginTable, shutdown) + sizeof(t.shutdown) };
    if (!hasShutdownField || t.shutdown == nullptr) problems.push_back("missing shutdown");
    return problems;
}

bool callUpdate(const PluginTable& t, double dt)
{
    const bool covered{ t.size >= offsetof(PluginTable, update) + sizeof(t.update) };
    if (!covered || t.update == nullptr) return false;
    t.update(dt);
    return true;
}

unitTests:
static int okInit(const void*) { return 0; }
static double g_dt{ 0 };
static void okUpdate(double dt) { g_dt = dt; }
static void okShutdown() {}
static PluginTable full() { return PluginTable{ static_cast<std::uint32_t>(sizeof(PluginTable)), 1, 0, "lantern", &okInit, &okUpdate, &okShutdown }; }
using P = std::vector<std::string>;
TEST("a good plugin") { CHECK(validatePlugin(full(), 1, 0).empty()); }
TEST("too small") { PluginTable t{ full() }; t.size = 4; CHECK(validatePlugin(t, 1, 0) == P({ "table too small" })); }
TEST("wrong major") { PluginTable t{ full() }; t.versionMajor = 2; CHECK(validatePlugin(t, 1, 5) == P({ "wrong major version" })); }
TEST("newer minor than the game") { PluginTable t{ full() }; t.versionMinor = 3; CHECK(validatePlugin(t, 1, 1) == P({ "needs a newer game" })); }
TEST("older minor is fine") { PluginTable t{ full() }; CHECK(validatePlugin(t, 1, 4).empty()); }
TEST("missing pieces") { PluginTable t{ full() }; t.name = ""; t.init = nullptr; t.shutdown = nullptr; CHECK(validatePlugin(t, 1, 0) == P({ "no name", "missing init", "missing shutdown" })); }
TEST("update is optional") { PluginTable t{ full() }; t.update = nullptr; CHECK(validatePlugin(t, 1, 0).empty()); CHECK(!callUpdate(t, 0.5)); }
TEST("update is called") { g_dt = 0; CHECK(callUpdate(full(), 0.25)); CHECK_NEAR(g_dt, 0.25, 1e-12); }
TEST("a short table has no update to call") { PluginTable t{ full() }; t.size = kMinimumSize; CHECK(!callUpdate(t, 1.0)); }

